window.AUTH=window.AUTH||{};window.AUTH["20-1573"]={"d":"20-1573","id":"2021/20-1573","n":"Viking River Cruises, Inc. v. Moriana","briefs":[{"k":"petitioner","label":"Brief of petitioner Viking River Cruises, Inc.","date":"2022-01-31","url":"https://www.supremecourt.gov/DocketPDF/20/20-1573/211808/20220131134107097_2022-01-31%20Viking%20Merits%20Brief%20FINAL.pdf","side":"pet","n":52},{"k":"respondent","label":"Brief of respondent Angie Moriana","date":"2022-03-02","url":"https://www.supremecourt.gov/DocketPDF/20/20-1573/215527/20220302165646882_Respondent%20Brief%20FINAL.pdf","side":"res","n":89},{"k":"reply","label":"Reply of petitioner Viking River Cruises, Inc.","date":"2022-03-18","url":"https://www.supremecourt.gov/DocketPDF/20/20-1573/218902/20220318122715670_20-1573%20Viking%20Reply%20Brief.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r43_gn0f.pdf","tr":true,"items":[{"t":"case","label":"Am. Express Co. v. Italian Colors Rest.","cite":"570 U.S. 228","y":2013,"id":"2012/12-133","sc":1,"op":2,"sum":"The Court held that a clause prohibiting class action suits was enforceable even though it would cause costly arbitration.","sumSrc":"Oyez","by":{"0":"5, 39","1":"5, 19, 22, 27","2":"4, 6"}},{"t":"case","label":"Amalgamated Transit Union, Loc. 1756 v. Superior Ct.","cite":"209 P.3d 937","y":2009,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/209/937/","op":6,"ar":2,"by":{"0":"6","1":"23","2":"9"}},{"t":"case","label":"AT&T Mobility LLC v. Concepcion","cite":"563 U.S. 333","y":2011,"id":"2010/09-893","sc":1,"op":17,"sum":"The Court held the Federal Arbitration Act preempts state laws that \"stand as obstacles to the FAA's objectives.\"","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Burrola v. U.S. Sec. Assocs., Inc.","cite":"2019 WL 480575","y":2019,"court":"S.D. Cal. Feb. 7","by":{"0":"45"}},{"t":"case","label":"Castillo v. Cava Mezze Grill, LLC","cite":"2018 WL 7501263","y":2018,"court":"C.D. Cal. Dec. 21","by":{"0":"44"}},{"t":"case","label":"Correia v. NB Baker Elec., Inc.","cite":"244 Cal.Rptr.3d 177","y":2019,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/244/177/","by":{"0":"26"}},{"t":"case","label":"Discover Bank v. Superior Ct.","cite":"113 P.3d 1100","y":2005,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/113/1100/","sum":"Concluding that some, but not all, classaction waivers “are unconscionable under California law and shall not be enforced”.","sumSrc":"brief:0","by":{"0":"31"}},{"t":"case","label":"EEOC v. Waffle House, Inc.","cite":"534 U.S. 279","y":2002,"id":"2001/99-1823","sc":1,"sum":"The Court held that the arbitration agreement did not bar the EEOC from pursuing victim-specific judicial relief in an ADA enforcement action. The Court reasoned that the EECO's statutory enforcement powers unambiguously authorized the EEOC to obtain the relief that it sought in its complaint, if it could prove its case against the employer.","sumSrc":"Oyez","by":{"0":"11, 36, 37","1":"5, 19, 44, 45","2":"2, 19"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"op":10,"ar":14,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"2, 8, 14, 17"}},{"t":"case","label":"Green Tree Fin. Corp.-Ala. v. Randolph","cite":"531 U.S. 79","y":2000,"id":"2000/99-1235","sc":1,"sum":"The Court held that an order compelling arbitration pursuant to the parties' agreement is a \"final decision with respect to an arbitration\" within the meaning of the Federal Arbitration Act making it immediately appealable pursuant to the FAA.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Huff v. Securitas Sec. Servs. USA, Inc.","cite":"233 Cal.Rptr.3d 502","y":2018,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/233/502/","by":{"0":"7","1":"33"}},{"t":"case","label":"Hume v. United States","cite":"132 U.S. 406","y":1889,"id":"scdb/1889-055","sc":1,"sum":"When a contract Is so extortionate and unconscionable on its face as to raise a presumption of fraud or to require but slight additional evidence to justify such presumption, fraud may be set up as a defence in an action at law with the same effect with which it could be set up in equity as a ground for affirmative relief; and if articles delivered in performance of such an unconscionable contract have been accepted …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Iskanian v. CLS Transp. L.A., LLC","cite":"327 P.3d 129","y":2014,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/327/129/","op":10,"sum":"Noting that based on Iskanian, California courts have uniformly “rejected efforts to split PAGA Page Proof Pending Publication claims into individual and representative components”.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"passim"}},{"t":"case","label":"Johnson v. Maxim Healthcare Servs., Inc.","cite":"281 Cal.Rptr.3d 478","y":2021,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/281/478/","sum":"Holding that plaintiff whose individual Labor Code claim would be time-barred can still pursue representative PAGA claim.","sumSrc":"brief:0","by":{"0":"7"}},{"t":"case","label":"Kim v. Reins Int’l Cal., Inc.","cite":"459 P.3d 1123","y":2020,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/459/1123/","op":4,"sum":"Noting that based on Iskanian, California courts have uniformly “rejected efforts to split PAGA Page Proof Pending Publication claims into individual and representative components”.","sumSrc":"opinion","by":{"0":"7, 24, 28, 30","1":"3, 4, 15, 30, 46","2":"20"}},{"t":"case","label":"Lamps Plus, Inc. v. Varela","cite":"139 S. Ct. 1407","y":2019,"id":"2018/17-988","sc":1,"op":7,"ar":2,"sum":"Under the Federal Arbitration Act, an ambiguous agreement cannot provide the necessary contractual basis for concluding that the parties agreed to submit to class arbitration.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20, 22","1":"34","2":"17"}},{"t":"case","label":"Lopez v. Friant & Assocs., LLC","cite":"224 Cal.Rptr.3d 1","y":2017,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/224/1/","by":{"0":"30"}},{"t":"case","label":"Magadia v. Wal-Mart Assocs., Inc.","cite":"999 F.3d 668","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/999/668/","op":1,"sum":"Holding that PAGA “lacks the procedural controls necessary to ensure that California” retains “substantial authority over the case” (internal quotation marks omitted).","sumSrc":"opinion","by":{"0":"38, 41, 42","1":"31, 33, 43"}},{"t":"case","label":"Marmet Health Care Ctr., Inc. v. Brown","cite":"565 U.S. 530","y":2012,"id":"2011/11-391","sc":1,"op":1,"sum":"Invalidating rule categorically barring arbitration of wrongful-death actions.","sumSrc":"opinion","by":{"0":"32","1":"6","2":"7"}},{"t":"case","label":"Mastrobuono v. Shearson Lehman Hutton, Inc.","cite":"514 U.S. 52","y":1995,"id":"1994/94-18","sc":1,"sum":"The arbitral award should have been enforced as within the scope of the contract between the parties.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39, 42"}},{"t":"case","label":"Mitsubishi Motors Corp. v. Soler Chrysler-Plymouth, Inc.","cite":"473 U.S. 614","y":1985,"id":"1984/83-1569","sc":1,"op":2,"ar":1,"sum":"The Supreme Court held that claims arising under the Sherman Act and encompassed in a valid arbitration clause in an international commercial transaction are arbitrable under the federal Arbitration Act. Justice John Paul Stevens dissented, arguing that a fair construction of the arbitration clause does not encompass antitrust claims.","sumSrc":"Oyez","by":{"0":"39","1":"19, 22, 24, 27","2":"6"}},{"t":"case","label":"Moorer v. Noble L.A. Events, Inc.","cite":"244 Cal.Rptr.3d 219","y":2019,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/244/219/","by":{"0":"8"}},{"t":"case","label":"Morgan Stanley Cap. Grp. Inc. v. Pub. Util. Dist. No. 1 of Snohomish Cnty.","cite":"554 U.S. 527","y":2008,"id":"2007/06-1457","sc":1,"sum":"Renegotiation is allowed only if the contract poses \"serious harm to the public interest.\" In this case, the Court decided 5-2 (Justices John G. Roberts and Stephen Breyer took no part in the decision) that the Federal Energy Regulatory Commission had failed to make sufficient factual findings in order to determine whether such serious harm could in fact occur.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Munoz v. Chipotle Mexican Grill, Inc.","cite":"189 Cal.Rptr.3d 134","y":2015,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/189/134/","by":{"0":"30"}},{"t":"case","label":"Perry v. Thomas","cite":"482 U.S. 483","y":1987,"id":"1986/86-566","sc":1,"sum":"Appellee brought suit in California Superior Court against his former employer and appellants, two of its employees, alleging breach of contract and related causes of action arising from a dispute over commissions on securities sales. After appellee refused to arbitrate, appellants filed a petition to compel arbitration under §§2 and 4 of the Federal Arbitration Act, which respectively provide that contractual …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"38","2":"7, 15"}},{"t":"case","label":"Porter v. Nabors Drilling USA, L.P.","cite":"854 F.3d 1057","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/854/1057/","sum":"Holding that exception to automatic bankruptcy stay for government actions does not apply to PAGA claim because it is “under [the plaintiff’s] control”.","sumSrc":"brief:0","by":{"0":"38"}},{"t":"case","label":"Prasad v. Pinnacle Prop. Mgmt Servs., LLC","cite":"2018 WL 4586960","y":2018,"court":"N.D. Cal. Sept. 25","by":{"0":"45"}},{"t":"case","label":"Preston v. Ferrer","cite":"552 U.S. 346","y":2008,"id":"2007/06-1463","sc":1,"op":2,"ar":1,"sum":"Noting that under the agreement, a party “relinquishe[d] no substantive rights . . . California law may accord him”.","sumSrc":"opinion","by":{"0":"32","1":"6, 13, 22"}},{"t":"case","label":"Provost v. YourMechanic, Inc.","cite":"269 Cal.Rptr.3d 903","y":2020,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/269/903/","by":{"0":"44"}},{"t":"case","label":"Rosales v. Uber Techs., Inc.","cite":"2020 WL 10485886","y":2020,"court":"Cal. Super. Ct. Mar. 12","by":{"0":"44"}},{"t":"case","label":"Rosales v. Uber Techs., Inc.","cite":"278 Cal.Rptr.3d 285","y":2021,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/278/285/","by":{"0":"43"}},{"t":"case","label":"Sakkab v. Luxottica Retail N. Am., Inc.","cite":"803 F.3d 425","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/803/425/","by":{"0":"passim","1":"passim","2":"1"}},{"t":"case","label":"Sanchez v. McDonald’s Rests. of Cal., Inc.","cite":"2017 WL 4620746","y":2017,"court":"Cal. Super. Ct. July 6","by":{"0":"47"}},{"t":"case","label":"State Farm Mut. Auto. Ins. Co. v. Campbell","cite":"538 U.S. 408","y":2003,"id":"2002/01-1289","sc":1,"sum":"The Court held that the punitive award of $145 million was neither reasonable nor proportionate to the wrong committed, and it was thus an irrational, arbitrary, and unconstitutional deprivation of the property of the insurer.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds Int’l Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"op":11,"sum":"The Court held that imposing class arbitration on parties who have not agreed to authorize class arbitration is inconsistent with the Federal Arbitration Act.","sumSrc":"Oyez","by":{"0":"4, 27"}},{"t":"case","label":"Turrieta v. Lyft, Inc.","cite":"284 Cal.Rptr.3d 767","y":2021,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/284/767/","op":1,"by":{"0":"47"}},{"t":"case","label":"United States ex rel. Welch v. My Left Foot Child.’s Therapy, LLC","cite":"871 F.3d 791","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/871/791/","sum":"Noting that question was “interesting” but resolving case on other grounds.","sumSrc":"brief:0","by":{"0":"40","1":"49"}},{"t":"case","label":"United States v. Bankers Ins. Co.","cite":"245 F.3d 315","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/245/315/","sum":"Holding arbitration is not inconsistent with the FCA or the government’s enforcement interests.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"Valdez v. Terminix Int’l Co. L.P.","cite":"681 F.App’x 592","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.App%E2%80%99x/681/592/","sum":"Holding that “PAGA claims are eligible for arbitration”.","sumSrc":"brief:0","by":{"0":"26"}},{"t":"case","label":"Volt Info. Scis., Inc. v. Bd. of Trs. of Leland Stanford Jr. Univ.","cite":"489 U.S. 468","y":1989,"id":"1988/87-1318","sc":1,"op":1,"sum":"A construction contract between appellant and appellee contained an agreement to arbitrate all disputes arising out of the contract and a choice-of-law clause providing that the contract would be governed by the law of \"the place where the Project is located.\" When a dispute arose under the contract, appellant made a formal demand for arbitration. In response, appellee filed an action against appellant in the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"op":2,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"0":"24","2":"12"}},{"t":"case","label":"Ward v. United Airlines, Inc.","cite":"466 P.3d 309","y":2020,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/466/309/","by":{"0":"47"}},{"t":"case","label":"Wesson v. Staples the Off. Superstore, LLC","cite":"283 Cal.Rptr.3d 846","y":2021,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/283/846/","by":{"0":"29, 48","1":"33","2":"9, 11"}},{"t":"case","label":"Williams v. Superior Ct.","cite":"398 P.3d 69","y":2017,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/398/69/","op":1,"ar":1,"by":{"0":"29, 47","2":"12, 13"}},{"t":"usc","label":"9 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/9/2","stext":{"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","paras":[[0,"A written provision in any maritime transaction or a contract evidencing a transaction involving commerce to settle by arbitration a controversy thereafter arising out of such contract or transaction, or the refusal to perform the whole or any part thereof, or an agreement in writing to submit to arbitration an existing controversy arising out of such a contract, transaction, or refusal, shall be valid, irrevocable, and enforceable, save upon such grounds as exist at law or in equity for the revocation of any contract or as otherwise provided in chapter 4."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/2?type=usc&year=mostrecent&link-type=html"},"op":10,"ar":1,"head":"§2. Validity, irrevocability, and enforcement of agreements to arbitrate","tname":"Arbitration","by":{"0":"passim","1":"passim"}},{"t":"usc","label":"9 U.S.C. § 3","url":"https://www.law.cornell.edu/uscode/text/9/3","stext":{"head":"§3. Stay of proceedings where issue therein referable to arbitration","paras":[[0,"If any suit or proceeding be brought in any of the courts of the United States upon any issue referable to arbitration under an agreement in writing for such arbitration, the court in which such suit is pending, upon being satisfied that the issue involved in such suit or proceeding is referable to arbitration under such an agreement, shall on application of one of the parties stay the trial of the action until such arbitration has been had in accordance with the terms of the agreement, providing the applicant for the stay is not in default in proceeding with such arbitration."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/3?type=usc&year=mostrecent&link-type=html"},"head":"§3. Stay of proceedings where issue therein referable to arbitration","tname":"Arbitration","by":{"0":"4, 19","1":"18"}},{"t":"usc","label":"9 U.S.C. § 4","url":"https://www.law.cornell.edu/uscode/text/9/4","stext":{"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","paras":[[0,"A party aggrieved by the alleged failure, neglect, or refusal of another to arbitrate under a written agreement for arbitration may petition any United States district court which, save for such agreement, would have jurisdiction under title 28, in a civil action or in admiralty of the subject matter of a suit arising out of the controversy between the parties, for an order directing that such arbitration proceed in the manner provided for in such agreement. Five days' notice in writing of such application shall be served upon the party in default. Service thereof shall be made in the manner provided by the Federal Rules of Civil Procedure. The court shall hear the parties, and upon being satisfied that the making of the agreement for arbitration or the failure to comply therewith is not in issue, the court shall make an order directing the parties to proceed to arbitration in accordance with the terms of the agreement. The hearing and proceedings, under such agreement, shall be within the district in which the petition for an order directing such arbitration is filed. If the making of the arbitration agreement or the failure, neglect, or refusal to perform the same be in issue, the court shall proceed summarily to the trial thereof. If no jury trial be demanded by the party alleged to be in default, or if the matter in dispute is within admiralty jurisdiction, the court shall hear and determine such issue. Where such an issue is raised, the party alleged to be in default may, except in cases of admiralty, on or before the return day of the notice of application, demand a jury trial of such issue, and upon such demand the court shall make an order referring the issue or issues to a jury in the manner provided by the Federal Rules of Civil Procedure, or may specially call a jury for that purpose. If the jury find that no agreement in writing for arbitration was made or that there is no default in proceeding thereunder, the proceeding shall be dismissed. If the jury find that an agreement for arbitration was made in writing and that there is a default in proceeding thereunder, the court shall make an order summarily directing the parties to proceed with the arbitration in accordance with the terms thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/4?type=usc&year=mostrecent&link-type=html"},"head":"§4. Failure to arbitrate under agreement; petition to United States court having jurisdiction for order to compel arbitration; notice and service thereof; hearing and determination","tname":"Arbitration","by":{"0":"4, 19","1":"18"}},{"t":"usc","label":"9 U.S.C. § 10","url":"https://www.law.cornell.edu/uscode/text/9/10","stext":{"head":"§10. Same; vacation; grounds; rehearing","paras":[[0,"(a) In any of the following cases the United States court in and for the district wherein the award was made may make an order vacating the award upon the application of any party to the arbitration—"],[1,"(1) where the award was procured by corruption, fraud, or undue means;"],[1,"(2) where there was evident partiality or corruption in the arbitrators, or either of them;"],[1,"(3) where the arbitrators were guilty of misconduct in refusing to postpone the hearing, upon sufficient cause shown, or in refusing to hear evidence pertinent and material to the controversy; or of any other misbehavior by which the rights of any party have been prejudiced; or"],[1,"(4) where the arbitrators exceeded their powers, or so imperfectly executed them that a mutual, final, and definite award upon the subject matter submitted was not made."],[0,"(b) If an award is vacated and the time within which the agreement required the award to be made has not expired, the court may, in its discretion, direct a rehearing by the arbitrators."],[0,"(c) The United States district court for the district wherein an award was made that was issued pursuant to section 580 of title 5 may make an order vacating the award upon the application of a person, other than a party to the arbitration, who is adversely affected or aggrieved by the award, if the use of arbitration or the award is clearly inconsistent with the factors set forth in section 572 of title 5."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/10?type=usc&year=mostrecent&link-type=html"},"head":"§10. Same; vacation; grounds; rehearing","tname":"Arbitration","by":{"0":"30","1":"18"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)"],"by":{"0":"6"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"0":"41"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(b)","(b)(4)(B)"],"stext":{"head":"§3730. Civil actions for false claims","paras":[[0,"(a) Responsibilities of the Attorney General.—The Attorney General diligently shall investigate a violation under section 3729. If the Attorney General finds that a person has violated or is violating section 3729, the Attorney General may bring a civil action under this section against the person."],[0,"(b) Actions by Private Persons.—(1) A person may bring a civil action for a violation of section 3729 for the person and for the United States Government. The action shall be brought in the name of the Government. The action may be dismissed only if the court and the Attorney General give written consent to the dismissal and their reasons for consenting."],[0,"(2) A copy of the complaint and written disclosure of substantially all material evidence and information the person possesses shall be served on the Government pursuant to Rule 4(d)(4) 1 of the Federal Rules of Civil Procedure. The complaint shall be filed in camera, shall remain under seal for at least 60 days, and shall not be served on the defendant until the court so orders. The Government may elect to intervene and proceed with the action within 60 days after it receives both the complaint and the material evidence and information."],[0,"(3) The Government may, for good cause shown, move the court for extensions of the time during which the complaint remains under seal under paragraph (2). Any such motions may be supported by affidavits or other submissions in camera. The defendant shall not be required to respond to any complaint filed under this section until 20 days after the complaint is unsealed and served upon the defendant pursuant to Rule 4 of the Federal Rules of Civil Procedure."],[0,"(4) Before the expiration of the 60-day period or any extensions obtained under paragraph (3), the Government shall—"],[1,"(A) proceed with the action, in which case the action shall be conducted by the Government; or"],[1,"(B) notify the court that it declines to take over the action, in which case the person bringing the action shall have the right to conduct the action."],[0,"(5) When a person brings an action under this subsection, no person other than the Government may intervene or bring a related action based on the facts underlying the pending action."],[0,"(c) Rights of the Parties to Qui Tam Actions.—(1) If the Government proceeds with the action, it shall have the primary responsibility for prosecuting the action, and shall not be bound by an act of the person bringing the action. Such person shall have the right to continue as a party to the action, subject to the limitations set forth in paragraph (2)."],[0,"(2)(A) The Government may dismiss the action notwithstanding the objections of the person initiating the action if the person has been notified by the Government of the filing of the motion and the court has provided the person with an opportunity for a hearing on the motion."],[0,"(B) The Government may settle the action with the defendant notwithstanding the objections of the person initiating the action if the court determines, after a hearing, that the proposed settlement is fair, adequate, and reasonable under all the circumstances. Upon a showing of good cause, such hearing may be held in camera."],[0,"(C) Upon a showing by the Government that unrestricted participation during the course of the litigation by the person initiating the action would interfere with or unduly delay the Government's prosecution of the case, or would be repetitious, irrelevant, or for purposes of harassment, the court may, in its discretion, impose limitations on the person's participation, such as—"],[1,"(i) limiting the number of witnesses the person may call;"],[1,"(ii) limiting the length of the testimony of such witnesses;"],[1,"(iii) limiting the person's cross-examination of witnesses; or"],[1,"(iv) otherwise limiting the participation by the person in the litigation."],[0,"(D) Upon a showing by the defendant that unrestricted participation during the course of the litigation by the person initiating the action would be for purposes of harassment or would cause the defendant undue burden or unnecessary expense, the court may limit the participation by the person in the litigation."],[0,"(3) If the Government elects not to proceed with the action, the person who initiated the action shall have the right to conduct the action. If the Government so requests, it shall be served with copies of all pleadings filed in the action and shall be supplied with copies of all deposition transcripts (at the Government's expense). When a person proceeds with the action, the court, without limiting the status and rights of the person initiating the action, may nevertheless permit the Government to intervene at a later date upon a showing of good cause."],[0,"(4) Whether or not the Government proceeds with the action, upon a showing by the Government that certain actions of discovery by the person initiating the action would interfere with the Government's investigation or prosecution of a criminal or civil matter arising out of the same facts, the court may stay such discovery for a period of not more than 60 days. Such a showing shall be conducted in camera. The court may extend the 60-day period upon a further showing in camera that the Government has pursued the criminal or civil investigation or proceedings with reasonable diligence and any proposed discovery in the civil action will interfere with the ongoing criminal or civil investigation or proceedings."],[0,"(5) Notwithstanding subsection (b), the Government may elect to pursue its claim through any alternate remedy available to the Government, including any administrative proceeding to determine a civil money penalty. If any such alternate remedy is pursued in another proceeding, the person initiating the action shall have the same rights in such proceeding as such person would have had if the action had continued under this section. Any finding of fact or conclusion of law made in such other proceeding that has become final shall be conclusive on all parties to an action under this section. For purposes of the preceding sentence, a finding or conclusion is final if it has been finally determined on appeal to the appropriate court of the United States, if all time for filing such an appeal with respect to the finding or conclusion has expired, or if the finding or conclusion is not subject to judicial review."],[0,"(d) Award to Qui Tam Plaintiff.—(1) If the Government proceeds with an action brought by a person under subsection (b), such person shall, subject to the second sentence of this paragraph, receive at least 15 percent but not more than 25 percent of the proceeds of the action or settlement of the claim, depending upon the extent to which the person substantially contributed to the prosecution of the action. Where the action is one which the court finds to be based primarily on disclosures of specific information (other than information provided by the person bringing the action) relating to allegations or transactions in a criminal, civil, or administrative hearing, in a congressional, administrative, or Government 2 Accounting Office report, hearing, audit, or investigation, or from the news media, the court may award such sums as it considers appropriate, but in no case more than 10 percent of the proceeds, taking into account the significance of the information and the role of the person bringing the action in advancing the case to litigation. Any payment to a person under the first or second sentence of this paragraph shall be made from the proceeds. Any such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(2) If the Government does not proceed with an action under this section, the person bringing the action or settling the claim shall receive an amount which the court decides is reasonable for collecting the civil penalty and damages. The amount shall be not less than 25 percent and not more than 30 percent of the proceeds of the action or settlement and shall be paid out of such proceeds. Such person shall also receive an amount for reasonable expenses which the court finds to have been necessarily incurred, plus reasonable attorneys' fees and costs. All such expenses, fees, and costs shall be awarded against the defendant."],[0,"(3) Whether or not the Government proceeds with the action, if the court finds that the action was brought by a person who planned and initiated the violation of section 3729 upon which the action was brought, then the court may, to the extent the court considers appropriate, reduce the share of the proceeds of the action which the person would otherwise receive under paragraph (1) or (2) of this subsection, taking into account the role of that person in advancing the case to litigation and any relevant circumstances pertaining to the violation. If the person bringing the action is convicted of criminal conduct arising from his or her role in the violation of section 3729, that person shall be dismissed from the civil action and shall not receive any share of the proceeds of the action. Such dismissal shall not prejudice the right of the United States to continue the action, represented by the Department of Justice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/31/3730?type=usc&year=mostrecent&link-type=html"},"head":"§3730. Civil actions for false claims","tname":"Money and Finance","by":{"0":"41","1":"32"}},{"t":"case","label":"Motion to Strike, Ortiz v. CVS Caremark Corp.","cite":"2014 WL 2445114","y":2014,"court":"N.D. Cal. Jan. 28","by":{"0":"47"}},{"t":"case","label":"14 Penn Plaza LLC v. Pyett","cite":"556 U.S. 247","y":2009,"id":"2008/07-581","sc":1,"sum":"The Court held that arbitration clauses in employment contracts are enforceable as a matter of federal law.","sumSrc":"Oyez","by":{"1":"19, 22, 23, 24, 28, 37"}},{"t":"case","label":"Achal v. Gate Gourmet Inc.","cite":"114 F. Supp. 3d 781","y":2015,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/114/781/","by":{"1":"24"}},{"t":"case","label":"Allied-Bruce Terminix Cos. v. Dobson","cite":"513 U.S. 265","y":1995,"id":"1994/93-1001","sc":1,"op":1,"sum":"The Court held that the Federal Arbitration Act applied to all disputes involving commerce, and thus the arbitration clause was valid and enforceable.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Angel v. Bullington","cite":"330 U.S. 183","y":1947,"id":"scdb/1946-055","sc":1,"sum":"The identical issue having been finally adjudicated in the state courts and the cause of action being barred there, it may not be relitigated in the federal courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Arias v. Super. Ct.","cite":"209 P.3d 923","y":2009,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/209/923/","op":5,"by":{"1":"2, 3, 4","2":"9"}},{"t":"case","label":"Arthur Andersen LLP v. Carlisle","cite":"556 U.S. 624","y":2009,"id":"2008/08-146","sc":1,"sum":"The Court found that regardless of whether the petitioner is eligible for a stay, a federal court of appeals has jurisdiction over a motion to stay under Section 16(a)(1) of the Federal Arbitration Act.","sumSrc":"Oyez","by":{"1":"43, 44"}},{"t":"case","label":"AT&T Techs., Inc. v. Commc’ns Workers","cite":"475 U.S. 643","y":1986,"id":"1985/84-1913","sc":1,"sum":"The issue whether, because of express exclusion or other evidence, the dispute over interpretation of Article 20 was subject to the arbitration clause, should have been decided by the District Court and reviewed by the Court of Appeals, and should not have been referred to the arbitrator.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Babcock v. Kijakazi","cite":"142 S. Ct. 641","y":2022,"id":"2021/20-480","sc":1,"sum":"Civil-service pension payments based on employment as a dual-status military technician are not payments based on “service as a member of a uniformed service” under 42 U. S. C. §415(a)(7)(A)(III).","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"Barney v. Latham","cite":"103 U.S. 205","y":1880,"id":"scdb/1880-168","sc":1,"by":{"1":"16"}},{"t":"case","label":"Baumann v. Chase Inv. Servs. Corp.","cite":"747 F.3d 1117","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/747/1117/","by":{"1":"4"}},{"t":"case","label":"Berkovitz v. Arbib & Houlberg, Inc.","cite":"130 N.E. 288","y":1921,"court":"N.Y.","url":"https://www.courtlistener.com/c/N.E./130/288/","by":{"1":"17, 19"}},{"t":"case","label":"Bernhardt v. Polygraphic Co. of Am.","cite":"350 U.S. 198","y":1956,"id":"1955/49","sc":1,"sum":"The judgment of the Court of Appeals is reversed and the cause is remanded to the District Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Booker v. Robert Half Int’l, Inc.","cite":"413 F.3d 77","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/413/77/","by":{"1":"7, 20, 42"}},{"t":"case","label":"Bridge v. Phoenix Bond & Indem. Co.","cite":"553 U.S. 639","y":2008,"id":"2007/07-210","sc":1,"sum":"The Court held in favor of Phoenix, stating that a plaintiff bringing a RICO claim based on mail fraud does not need to show that it actually relied on the defendant's misrepresentations. Plaintiffs do not lack standing merely because the false statements were made to a third party.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Bright v. 99¢ Only Stores","cite":"118 Cal.Rptr.3d 723","y":2010,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.Rptr.3d/118/723/","by":{"1":"25"}},{"t":"case","label":"Brnovich v. Democratic Nat’l Comm.","cite":"141 S. Ct. 2321","y":2021,"id":"2020/19-1257","sc":1,"sum":"Arizona’s challenged voting regulations governing precinct-based election-day voting (rejecting ballots cast in the wrong precinct) and early mail-in voting (making it a crime for anyone other than an authorized proxy to possess the early ballot of another voter) do not violate §2 of the Voting Rights Act of 1965; Arizona House Bill 2023 (enacting the early mail-in voting regulations) was not enacted with a racially discriminatory purpose.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15"}},{"t":"case","label":"Buckeye Check Cashing, Inc. v. Cardegna","cite":"546 U.S. 440","y":2006,"id":"2005/04-1264","sc":1,"sum":"The 7-1 majority (Justice Samuel Alito not participating) ruled that challenges to the legality of a contract as a whole must be argued before the arbitrator rather than a court.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Canela v. Costco Wholesale Corp.","cite":"971 F.3d 845","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/971/845/","by":{"1":"3, 30"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"ar":2,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"1":"35","2":"14"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 24"}},{"t":"case","label":"CompuCredit Corp. v. Greenwood","cite":"565 U.S. 95","y":2012,"id":"2011/10-948","sc":1,"sum":"The Court held that the Credit Repair Organizations Act does not give credit card users the right to bring a suit against their card companies in court.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Dan’s City Used Cars, Inc. v. Pelkey","cite":"569 U.S. 251","y":2013,"id":"2012/12-52","sc":1,"sum":"The Court found that the Federal Aviation Administration Authorization Act does not override state law regarding transportation of property.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Dean Witter Reynolds, Inc. v. Byrd","cite":"470 U.S. 213","y":1985,"id":"1984/83-1708","sc":1,"op":1,"sum":"The District Court erred in refusing to grant petitioner's motion to compel arbitration of the state claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Devlin v. Scardelletti","cite":"536 U.S. 1","y":2002,"id":"2001/01-417","sc":1,"op":2,"sum":"The Court held that nonnamed class members like Devlin, who have objected in a timely manner to approval of the settlement at the fairness hearing, have the power to bring an appeal without first intervening.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Doctor’s Assocs. v. Casarotto","cite":"517 U.S. 681","y":1996,"id":"1995/95-559","sc":1,"sum":"Authored by Justice Ruth Bader Ginsburg, the Court ruled that Montana's first-page notice requirement, 27-5-114(4), which governs not \"any contract,\" but specifically and solely contracts \"subject to arbitration,\" conflicts with the Federal Arbitration Act (FAA) and is therefore displaced by the federal measure.","sumSrc":"Oyez","by":{"1":"13, 38","2":"18"}},{"t":"case","label":"Erie R. Co. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"ar":4,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"First Options of Chicago, Inc. v. Kaplan","cite":"514 U.S. 938","y":1995,"id":"1994/94-560","sc":1,"op":1,"ar":2,"sum":"The Court held that the arbitrability of the Kaplan/First Options dispute was subject to independent review by the courts and that, rather than a special abuse of discretion standard, courts of appeals should apply ordinary standards when reviewing district court decisions upholding arbitration awards. \"We conclude that, because the Kaplans did not clearly agree to submit the question of arbitrability to arbitration, the Court of Appeals was correct in finding that the arbitrability of the Kaplan/First Options dispute was subject to independent review by the courts,\" wrote Justice Breyer for the Court.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Gasperini v. Center for Humanities, Inc.","cite":"518 U.S. 415","y":1996,"id":"1995/95-719","sc":1,"sum":"In a split majority decision, authored by Justice Ruth Bader Ginsburg, the Court ruled that New York's law controlling compensation awards for excessiveness or inadequacy can be given effect, without detriment to the Seventh Amendment, if the review standard is applied by the federal trial court judge, with appellate control of the trial court's ruling confined to \"abuse of discretion.\" Justice John Paul Stevens dissented regarding the judgment of the Court but agreed with most of the majority's reasoning.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"GE Energy Power Conversion France SAS, Corp. v. Outokumpu Stainless USA, LLC","cite":"140 S. Ct. 1637","y":2020,"id":"2019/18-1048","sc":1,"sum":"The Court held that the Convention on the Recognition and Enforcement of Foreign Arbitral Awards does not prohibit the application of domestic equitable estoppel doctrine to allow a nonsignatory to an arbitration agreement to compel arbitration.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Gilmer v. Interstate/Johnson Lane Corp.","cite":"500 U.S. 20","y":1991,"id":"1990/90-18","sc":1,"sum":"An ADEA claim can be subjected to compulsory arbitration.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 24, 28"}},{"t":"case","label":"Goldman Sachs Grp. v. Ark. Teacher Ret. Sys.","cite":"141 S. Ct. 1951","y":2021,"id":"2020/20-222","sc":1,"sum":"The generic nature of a misrepresentation in connection with the sale of securities often is important evidence of price impact that courts should consider at class certification; defendants bear the burden of persuasion to prove a lack of price impact by a preponderance of the evidence at class certification.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28"}},{"t":"case","label":"Goodall-Sanford, Inc. v. United Textile Workers","cite":"353 U.S. 550","y":1957,"id":"1956/262","sc":1,"sum":"1. In a suit by a union under § 301 (a) of the Labor Management Relations Act of 1947, a Federal District Court has authority to compel compliance by an employer with an agreement to arbitrate disputes arising under a collective bargaining agreement with the union. Textile Workers v. Lincoln Mills, ante, p. 448.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Granite Rock Co. v. Int’l B’hood of Teamsters","cite":"561 U.S. 287","y":2010,"id":"2009/08-1214","sc":1,"op":1,"sum":"The Court held that federal courts have jurisdiction to determine whether or not a collective bargaining agreement was formed between two parties when the agreement is disputed, but neither party makes a challenge to the arbitration clause contained in the agreement.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Howard v. Ferrellgas Partners","cite":"748 F.3d 975","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/748/975/","by":{"1":"15"}},{"t":"case","label":"John Wiley & Sons, Inc. v. Livingston","cite":"376 U.S. 543","y":1964,"id":"1963/91","sc":1,"op":2,"sum":"Respondent labor union brought an action under § 301 of the Labor Management Relations Act to compel arbitration under a collective bargaining agreement executed by a company which the petitioner acquired by merger. The District Court denied relief but the Court of Appeals reversed and directed arbitration.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Kansas v. Garcia","cite":"140 S. Ct. 791","y":2020,"id":"2019/17-834","sc":1,"sum":"A case in which the Court upheld Kansas's prosecution of noncitizens who used stolen social security numbers to gain employment.","sumSrc":"Oyez","by":{"1":"25, 26"}},{"t":"case","label":"Kindred Nursing Ctrs. Ltd. P’ship v. Clark","cite":"137 S. Ct. 1421","y":2017,"id":"2016/16-32","sc":1,"op":3,"sum":"The Court held that the Federal Arbitration Act (FAA) preempts Kentucky state-law precedent that requires a clear statement in the power of attorney agreement in order to grant an attorney-in-fact the power to bind her principal to an arbitration agreement.","sumSrc":"Oyez","by":{"1":"21, 38, 39, 40","2":"18"}},{"t":"case","label":"Medtronic, Inc. v. Lohr","cite":"518 U.S. 470","y":1996,"id":"1995/95-754","sc":1,"sum":"The Court held that the Court of Appeals decision was reversed insofar as it held that any of the claims were pre-empted and affirmed insofar as it rejected any pre-emption defense. In a 9-0 vote, the Court allowed the lawsuit based on alleged defects in the pacemaker's design to proceed.","sumSrc":"Oyez","by":{"1":"8"}},{"t":"case","label":"Nashville, C. & St. L. Ry. v. Wallace","cite":"288 U.S. 249","y":1933,"id":"scdb/1932-112","sc":1,"sum":"that a judgment upholding the tax and affirming dismissal of the bill on the merits, was reviewable by this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"36"}},{"t":"case","label":"Nolde Bros. v. Bakery Workers","cite":"430 U.S. 243","y":1977,"id":"1976/75-1198","sc":1,"sum":"Respondent's claim for severance pay under the expired contract is subject to resolution under the contract's arbitration terms.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Prima Paint Corp. v. Flood & Conklin Mfg. Co.","cite":"388 U.S. 395","y":1967,"id":"1966/343","sc":1,"by":{"1":"38"}},{"t":"case","label":"Ragan v. Merchants Transfer & Warehouse Co.","cite":"337 U.S. 530","y":1949,"id":"scdb/1948-099","sc":1,"sum":"The suit was barred by the state statute of limitations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Ragone v. Atl. Video at Manhattan Ctr.","cite":"595 F.3d 115","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/595/115/","by":{"1":"42"}},{"t":"case","label":"Red Cross Line v. Atl. Fruit Co.","cite":"264 U.S. 109","y":1924,"id":"scdb/1923-067","sc":1,"sum":"1. A decision of the highest court of a State excluding maritime contracts from the operation of a state statute, not as a matter of statutory construction but due to its opinion that the Federal Constitution so requires, presents a constitutional question reviewable here.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17, 19"}},{"t":"case","label":"Rodriguez de Quijas v. Shearson/Am. Express, Inc.","cite":"490 U.S. 477","y":1989,"id":"1988/88-385","sc":1,"sum":"A predispute agreement to arbitrate claims under the Securities Act of 1933 is enforceable and resolution of the claims only in a judicial forum is not required.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 24"}},{"t":"case","label":"Saucillo v. Peck, __ F.4th __","cite":"2022 WL 414692","y":2022,"court":"9th Cir.","by":{"1":"4, 30, 31, 43"}},{"t":"case","label":"Scherk v. Alberto-Culver Co.","cite":"417 U.S. 506","y":1974,"id":"1973/73-781","sc":1,"op":1,"sum":"The arbitration clause is to be respected and enforced by federal courts in accord with the explicit provisions of the United States Arbitration Act that an arbitration agreement, such as is here involved, \"shall be valid, irrevocable, and enforceable, save upon such grounds as exist at law or in equity for the revocation of any contract.\" 9 U. S. C. §§ 1, 2. Wilko v. Swan, supra, distinguished.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Serrano v. Unruh","cite":"652 P.2d 985","y":1982,"court":"Cal.","url":"https://www.courtlistener.com/c/P.2d/652/985/","by":{"1":"48"}},{"t":"case","label":"Shady Grove Ortho. Assocs. v. Allstate Ins. Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"op":9,"sum":"The Court held that Section 901(b) of the New York Rules of Civil Procedure does not preclude a federal court ruling on entities from different jurisdictions from hearing a class action under Rule 23 of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Shearson/Am. Express, Inc. v. McMahon","cite":"482 U.S. 220","y":1987,"id":"1986/86-44","sc":1,"sum":"Respondents were customers of petitioner Shearson/American Express Inc. (Shearson), a brokerage firm registered with the Securities and Exchange Commission (SEC), under customer agreements providing for arbitration of any controversy relating to their accounts. Respondents filed suit in Federal District Court against Shearson and its representative (also a petitioner here) who handled their accounts, alleging …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 24, 28"}},{"t":"case","label":"Sheriff v. Gillie","cite":"578 U.S. 317","y":2016,"id":"2015/15-338","sc":1,"sum":"The Court held that, regardless of whether special counsel appointed by the Attorney General to collect debts are “state officers” under the Federal Debt Collection Practices Act, the use of Attorney General letterhead by such special counsel is not materially misleading.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Tarbell v. Rutland R. Co.","cite":"51 A. 6","y":1901,"court":"Vt.","url":"https://www.courtlistener.com/c/A./51/6/","by":{"1":"21"}},{"t":"case","label":"Toledo S.S. Co. v. Zenith Transp. Co.","cite":"184 F. 391","y":1911,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F./184/391/","by":{"1":"41"}},{"t":"case","label":"U.S. Forest Serv. v. Cowpasture River Pres. Ass’n","cite":"140 S. Ct. 1837","y":2020,"id":"2019/18-1584","sc":1,"sum":"The Court held that the U.S. Forest Service has the authority to grant rights-of-way under the Mineral Leasing Act through lands traversed by the Appalachian Trail within national forests.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Union Constr. Co. v. W. Union Tel. Co.","cite":"163 Cal. 298","y":1912,"url":"https://www.courtlistener.com/c/Cal./163/298/","by":{"1":"21"}},{"t":"case","label":"United Steelworkers v. Enterprise Wheel & Car Corp","cite":"363 U.S. 593","y":1960,"id":"1959/538","sc":1,"sum":"The judgment of the District Court should have been affirmed with a modification requiring the specific amounts due the employees to be definitely determined by arbitration.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"United Steelworkers v. Warrior & Gulf Nav. Co.","cite":"363 U.S. 574","y":1960,"id":"1959/443","sc":1,"sum":"It erred in doing so, and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Va. Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15, 25, 26"}},{"t":"case","label":"Vimar Seguros y Reaseguros, S.A. v. M/V Sky Reefer","cite":"515 U.S. 528","y":1995,"id":"1994/94-623","sc":1,"sum":"COGSA does not nullify foreign arbitration clauses contained in maritime bills of lading.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 20"}},{"t":"case","label":"Woods v. Interstate Realty Co.","cite":"337 U.S. 535","y":1949,"id":"scdb/1948-100","sc":1,"sum":"The motion for summary judgment was properly granted. Erie R. Co. v. Tompkins, 304 U. S.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"ZB, N.A. v. Super. Ct.","cite":"448 P.3d 239","y":2019,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/448/239/","op":1,"by":{"1":"3, 4, 10, 14, 46"}},{"t":"usc","label":"9 U.S.C. § 7","url":"https://www.law.cornell.edu/uscode/text/9/7","by":{"1":"18"}},{"t":"usc","label":"9 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/9/9","by":{"1":"18"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"1":"24, 29, 33"}},{"t":"case","label":"Claimant v. Respondent","cite":"2013 WL 3810904","y":2013,"court":"AAA May 9","by":{"2":"5"}},{"t":"case","label":"Claimant v. Respondent","cite":"2015 WL 10489631","y":2015,"court":"AAA Nov. 12","by":{"2":"5"}},{"t":"case","label":"Iskanian v. CLS Transp. Los Angeles, LLC","cite":"2016 WL 10706257","y":2016,"court":"Cal. Super. Ct. June 17","by":{"2":"16"}},{"t":"case","label":"MeadWestvaco Corp. ex rel. Mead Corp. v. Ill. Dep’t of Revenue","cite":"553 U.S. 16","y":2008,"id":"2007/06-1413","sc":1,"sum":"The Court sent the case back to the state appellate court holding that the court had previously applied the wrong test in defining the relationship between Lexis/Nexis and Meadwestvaco.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"Southland Corp. v. Keating","cite":"465 U.S. 1","y":1984,"id":"1983/82-500","sc":1,"ar":1,"sum":"Appellant Southland Corp. (hereafter appellant) is the owner and franchisor of 7-Eleven convenience stores. Appellees are 7-Eleven franchisees. Each franchise agreement between appellant and appellees contains a clause requiring arbitration of any controversy or claim arising out of or relating to the agreement or breach thereof. Several of the appellees filed individual actions against appellant in California …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"21"}},{"t":"case","label":"Van Orden v. Perry","cite":"545 U.S. 677","y":2005,"id":"2004/03-1500","sc":1,"sum":"The Court held that a Ten Commandments monument erected on the state capitol building's grounds did not violate the establishment clause of the First Amendment.","sumSrc":"Oyez","by":{"2":"22"}}]};